// Validates the call and works out which of the two jobs this is.
//
// The mode is explicit when the caller sends one. When it does not, it is inferred from the
// shape of the request - but an ambiguous request throws rather than guessing, because
// guessing wrong here either records a cost that never happened or waves through a call
// that should have been stopped.
const SUPABASE_URL = '';            // TODO: https://<project>.supabase.co
const ALERT_CHAT_ID = '';           // TODO: the Telegram chat that receives alerts
const TIMEZONE = 'Europe/Madrid';   // the budget day resets at local midnight, not UTC
const MAX_TOKENS = 10000000;

if (!SUPABASE_URL) throw new Error('SUPABASE_URL is not configured in "Prepare"');
// The alert is not optional decoration: a cap that refuses a call without telling anyone
// looks exactly like a workflow that mysteriously stopped working.
if (!ALERT_CHAT_ID) throw new Error('ALERT_CHAT_ID is not configured in "Prepare"');

const input = $input.first().json || {};
const hasUsage = input.usage !== undefined && input.usage !== null;
const hasEstimate = input.estimated_cost_usd !== undefined && input.estimated_cost_usd !== null;

let mode = input.mode;
if (mode === undefined || mode === null || mode === '') {
  if (hasUsage && !hasEstimate) mode = 'log';
  else if (hasEstimate && !hasUsage) mode = 'check';
  else if (hasUsage && hasEstimate) throw new Error('ambiguous request: send mode "log" or "check" explicitly');
  else throw new Error('send either usage (to log) or estimated_cost_usd (to check)');
}
if (mode !== 'log' && mode !== 'check') {
  throw new Error('mode must be "log" or "check", got ' + JSON.stringify(input.mode));
}

const base = SUPABASE_URL.replace(/\/+$/, '');

// The day boundary is local. A UTC day would reset the budget at 01:00 or 02:00 local
// time, which is neither what a daily limit means to a person nor what the report covers.
const dayStart = DateTime.now().setZone(TIMEZONE).startOf('day');

const out = {
  mode,
  timezone: TIMEZONE,
  chatId: ALERT_CHAT_ID,
  dayStart: dayStart.toISO(),
  configUrl: base + '/rest/v1/llm_guard_config?select=daily_limit_usd&id=eq.1',
  spendUrl: base + '/rest/v1/rpc/llm_spend_since',
  usageUrl: base + '/rest/v1/llm_usage',
  priceUrl: '',
};

const count = (v, name) => {
  const n = Number(v);
  if (!Number.isFinite(n) || !Number.isInteger(n) || n < 0 || n > MAX_TOKENS) {
    throw new Error(name + ' must be a whole number between 0 and ' + MAX_TOKENS + ', got ' + JSON.stringify(v));
  }
  return n;
};

if (mode === 'log') {
  const workflowName = String(input.workflow_name || '').trim();
  if (!workflowName) throw new Error('workflow_name is required to log');
  const model = String(input.model || '').trim();
  if (!model) throw new Error('model is required to log');

  const usage = input.usage || {};
  out.workflowName = workflowName;
  out.model = model;
  out.inputTokens = count(usage.input_tokens, 'input_tokens');
  out.outputTokens = count(usage.output_tokens, 'output_tokens');
  out.purpose = input.purpose === undefined || input.purpose === null
    ? null
    : String(input.purpose).slice(0, 500);
  out.priceUrl = base + '/rest/v1/model_prices?select=model,in_per_mtok,out_per_mtok&model=eq.'
    + encodeURIComponent(model);
} else {
  const est = Number(input.estimated_cost_usd);
  if (!Number.isFinite(est) || est < 0) throw new Error('estimated_cost_usd must be a number of 0 or more');
  out.estimated = est;
}

return [{ json: out }];

// Turns tokens into money using the price list.
//
// An unknown model is recorded but not priced. The tokens are real and belong in the
// ledger, but inventing a number for them would put a fiction into the total. So cost
// stays at zero and priced is false, which is what makes the day's total a floor rather
// than a guess - and the alert below is what stops that floor from going unnoticed.
const state = $('Prepare').first().json;
const res = $input.first().json || {};
const rows = Array.isArray(res.body) ? res.body : Array.isArray(res) ? res : [];
const price = rows.find((r) => r && r.model === state.model) || null;

const round6 = (n) => Math.round(n * 1e6) / 1e6;

let cost = 0;
let priced = false;
if (price) {
  const inRate = Number(price.in_per_mtok);
  const outRate = Number(price.out_per_mtok);
  if (!Number.isFinite(inRate) || !Number.isFinite(outRate) || inRate < 0 || outRate < 0) {
    throw new Error('the model_prices row for ' + state.model + ' has a price that is not a number');
  }
  cost = round6((state.inputTokens / 1e6) * inRate + (state.outputTokens / 1e6) * outRate);
  priced = true;
}

return [{
  json: {
    ...state,
    cost,
    priced,
    row: {
      workflow_name: state.workflowName,
      model: state.model,
      input_tokens: state.inputTokens,
      output_tokens: state.outputTokens,
      cost_usd: cost,
      priced,
      purpose: state.purpose,
    },
    alertText: priced ? null : [
      'Unpriced model: ' + state.model,
      'Logged by: ' + state.workflowName,
      'Tokens: ' + state.inputTokens + ' in, ' + state.outputTokens + ' out',
      'Recorded at zero cost, so the daily cap is blind to it. Add it to model_prices.',
    ].join('\n'),
  },
}];

// The caller gets back what was recorded, including whether it was actually priced.
// A caller that believes a call was free when it was merely unpriced will keep going.
const state = $('Price the call').first().json;

return [{
  json: {
    logged: true,
    workflow_name: state.workflowName,
    model: state.model,
    input_tokens: state.inputTokens,
    output_tokens: state.outputTokens,
    cost_usd: state.cost,
    priced: state.priced,
  },
}];

// Compares what has been spent today, plus what the caller is about to spend, against
// the cap.
const state = $('Prepare').first().json;

const cfgRes = $('Read the cap').first().json || {};
const cfgRows = Array.isArray(cfgRes.body) ? cfgRes.body : Array.isArray(cfgRes) ? cfgRes : [];
const limit = Number(cfgRows[0] && cfgRows[0].daily_limit_usd);
// A missing or unreadable cap must not read as "no limit". Throwing here refuses the call,
// which is the safe direction: a blocked call is a nuisance, an unbounded bill is not.
if (!Number.isFinite(limit) || limit < 0) {
  throw new Error('daily_limit_usd could not be read from llm_guard_config; apply schema.sql');
}

const spendRes = $input.first().json || {};
const spendRows = Array.isArray(spendRes.body) ? spendRes.body : Array.isArray(spendRes) ? spendRes : [];
const agg = spendRows[0] || {};
// Number(null) is 0, so a null total would read as "nothing spent today" and wave through
// a call that the real total might well have blocked. A total that is absent or null is a
// broken answer, not a quiet day, and has to be treated as one.
if (agg.total_usd === undefined || agg.total_usd === null) {
  throw new Error('llm_spend_since did not return a usable total');
}
const spent = Number(agg.total_usd);
if (!Number.isFinite(spent) || spent < 0) {
  throw new Error('llm_spend_since did not return a usable total');
}
const unpriced = Number(agg.unpriced || 0);

const round6 = (n) => Math.round(n * 1e6) / 1e6;
const projected = round6(spent + state.estimated);
// Exactly at the cap is allowed; the spec refuses what exceeds it.
const allowed = projected <= limit;

return [{
  json: {
    ...state,
    allowed,
    spent: round6(spent),
    projected,
    limit,
    unpriced,
    calls: Number(agg.calls || 0),
    alertText: allowed ? null : [
      'Daily LLM cap reached.',
      'Spent today: $' + round6(spent).toFixed(4),
      'This call would add: $' + state.estimated.toFixed(4),
      'Cap: $' + limit.toFixed(2),
      unpriced > 0
        ? unpriced + ' call(s) today used an unpriced model, so the real total is higher.'
        : null,
      'Refused. The caller was told to stop.',
    ].filter(Boolean).join('\n'),
  },
}];

// The verdict the caller is expected to obey. Nothing here can force it to.
const state = $('Decide').first().json;

return [{
  json: {
    allowed: state.allowed,
    spent_today: state.spent,
    estimated: state.estimated,
    projected: state.projected,
    limit: state.limit,
    currency: 'USD',
    day_start: state.dayStart,
    timezone: state.timezone,
    calls_today: state.calls,
    // Greater than zero means spent_today is a floor, not the truth: some of today's calls
    // used a model with no price.
    unpriced_today: state.unpriced,
  },
}];
